// One clean row per keyword and country; notes about the input are skipped.
return $input.all().filter(i => i.json.keyword && i.json.country).map(i => ({ json: {
  keyword: i.json.keyword, country: i.json.country, volume: i.json.searchVolume, cpcUsd: i.json.cpcUsd,
  competition: i.json.competition, trend: i.json.trendDirection, status: i.json.status } }));
